#include <iostream>
#include <stdexcept>
#include <string>
#include <sstream>

// ── BankAccount — encapsulates the invariant: balance >= 0 ────────────────
class BankAccount {
public:
    BankAccount(std::string owner, double initial)
        : owner_(std::move(owner))
        , balance_(0.0)
        , txCount_(0)
    {
        if (initial < 0)
            throw std::invalid_argument("Initial balance cannot be negative");
        balance_ = initial;    // set after validation — invariant established
    }

    // Mutating operations — preserve the invariant
    void deposit(double amount) {
        if (amount <= 0) throw std::invalid_argument("Deposit must be positive");
        balance_ += amount;
        ++txCount_;
    }

    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance_) return false;
        balance_ -= amount;
        ++txCount_;
        return true;
    }

    // Const accessors — do not modify state
    const std::string& owner()   const { return owner_; }
    double             balance()  const { return balance_; }
    int                txCount()  const { return txCount_; }

    // Pretty-print
    friend std::ostream& operator<<(std::ostream& os, const BankAccount& a) {
        return os << "Account[" << a.owner_ << "] $"
                  << a.balance_ << " (" << a.txCount_ << " tx)";
    }

private:
    // Invariant: balance_ >= 0
    std::string owner_;
    double      balance_;
    int         txCount_;
};

// ── Value type: Money ─────────────────────────────────────────────────────
class Money {
public:
    static Money fromCents(long cents) { return Money(cents); }
    static Money fromDollars(double d) { return Money(static_cast<long>(d * 100)); }

    Money operator+(const Money& o) const { return Money(cents_ + o.cents_); }
    Money operator-(const Money& o) const { return Money(cents_ - o.cents_); }
    bool  operator==(const Money& o) const { return cents_ == o.cents_; }
    bool  operator< (const Money& o) const { return cents_ < o.cents_; }

    friend std::ostream& operator<<(std::ostream& os, const Money& m) {
        long dollars = m.cents_ / 100;
        long cents   = m.cents_ % 100;
        return os << "$" << dollars << "." << (cents < 10 ? "0" : "") << cents;
    }
private:
    explicit Money(long cents) : cents_(cents) {}
    long cents_;
};

int main() {
    std::cout << "=== Day 03: Classes & Encapsulation ===\n\n";

    // ── BankAccount demo ───────────────────────────────────────────────────
    BankAccount alice("Alice", 1000.0);
    std::cout << alice << "\n";

    alice.deposit(500.0);
    std::cout << "After deposit(500):  " << alice << "\n";

    bool ok = alice.withdraw(200.0);
    std::cout << "withdraw(200) -> " << (ok ? "ok" : "fail") << ": " << alice << "\n";

    bool fail = alice.withdraw(2000.0);   // exceeds balance
    std::cout << "withdraw(2000) -> " << (fail ? "ok" : "denied") << ": " << alice << "\n";

    // Invariant: balance never goes negative
    std::cout << "Balance: $" << alice.balance() << " (always >= 0)\n\n";

    // ── const-correctness demo ─────────────────────────────────────────────
    const BankAccount bob("Bob", 250.0);
    // bob.deposit(100);     // ❌ won't compile: deposit is non-const
    std::cout << "Const account owner: " << bob.owner() << "\n";
    std::cout << "Const account balance: $" << bob.balance() << "\n\n";

    // ── Money value type ───────────────────────────────────────────────────
    auto price    = Money::fromDollars(19.99);
    auto shipping = Money::fromDollars(4.95);
    auto total    = price + shipping;
    std::cout << "Price: " << price << "  Shipping: " << shipping
              << "  Total: " << total << "\n";

    // ── Exception for invalid construction ────────────────────────────────
    try {
        BankAccount bad("Bad", -100.0);
    } catch (const std::invalid_argument& e) {
        std::cout << "\nCaught: " << e.what() << " (invariant protected)\n";
    }

    return 0;
}
